mapper.update:
UPDATE oms_ticket
SET remaining_inventory = remaining_inventory - #{qty}
WHERE id = #{id}
  AND remaining_inventory >= #{qty}

UPDATE oms_ticket
SET remaining_inventory = remaining_inventory - #{qty}
WHERE id = #{id}
  AND remaining_inventory - #{qty} >= #{reservedQuota}

UPDATE oms_ticket
SET remaining_inventory = remaining_inventory + #{qty}
WHERE id = #{id}
  AND remaining_inventory + #{qty} <= total_inventory
